def glow(x,y):
    return e(x,y,17,17,'#d68b7130')+e(x,y,9,9,'#d68b7145')+p(f'M{x-21} {y-10}l-5 -3M{x+21} {y-10}l5 -3M{x+17} {y+16}l4 4',stroke='#bf795d')
